<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function vetra_component_breadcrumbs() { if ( is_front_page() ) { return; } echo '<nav class="vetra-breadcrumbs" aria-label="' . esc_attr__( 'مسیر صفحه', 'vetra-portal' ) . '"><a href="' . esc_url( home_url( '/' ) ) . '">' . esc_html__( 'خانه', 'vetra-portal' ) . '</a><span aria-hidden="true">/</span><span>' . esc_html( wp_strip_all_tags( get_the_archive_title() ?: get_the_title() ) ) . '</span></nav>'; }
function vetra_component_post_meta() { ?><div class="vetra-entry-meta"><time datetime="<?php echo esc_attr( get_the_date( DATE_W3C ) ); ?>"><?php echo esc_html( get_the_date() ); ?></time><?php if ( get_the_modified_time( 'U' ) !== get_the_time( 'U' ) ) : ?><span><?php printf( esc_html__( 'به‌روزرسانی: %s', 'vetra-portal' ), esc_html( get_the_modified_date() ) ); ?></span><?php endif; ?><?php if ( get_the_author() ) : ?><span><?php printf( esc_html__( 'نویسنده: %s', 'vetra-portal' ), esc_html( get_the_author() ) ); ?></span><?php endif; ?></div><?php }
function vetra_component_share() { if ( ! is_singular() ) { return; } $url = rawurlencode( get_permalink() ); $title = rawurlencode( get_the_title() ); ?><nav class="vetra-share" aria-label="<?php esc_attr_e( 'اشتراک‌گذاری', 'vetra-portal' ); ?>"><span><?php esc_html_e( 'اشتراک‌گذاری:', 'vetra-portal' ); ?></span><a href="https://www.linkedin.com/sharing/share-offsite/?url=<?php echo esc_attr( $url ); ?>" rel="noopener noreferrer" target="_blank"><?php esc_html_e( 'LinkedIn', 'vetra-portal' ); ?></a><a href="https://t.me/share/url?url=<?php echo esc_attr( $url ); ?>&text=<?php echo esc_attr( $title ); ?>" rel="noopener noreferrer" target="_blank"><?php esc_html_e( 'Telegram', 'vetra-portal' ); ?></a></nav><?php }
function vetra_component_related() { $related = get_posts( array( 'post__not_in' => array( get_the_ID() ), 'posts_per_page' => 3, 'category__in' => wp_get_post_categories( get_the_ID() ), 'no_found_rows' => true ) ); if ( ! $related ) { return; } ?><section class="vetra-related" aria-labelledby="related-title"><h2 id="related-title"><?php esc_html_e( 'نوشته‌های مرتبط', 'vetra-portal' ); ?></h2><div class="vetra-related-grid"><?php foreach ( $related as $post ) : setup_postdata( $post ); ?><article><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3><p><?php echo esc_html( get_the_date() ); ?></p></article><?php endforeach; wp_reset_postdata(); ?></div></section><?php }
